/**
 * Mandatory P0 end-to-end scenarios (master prompt §13) that earlier suites covered only at the rules level.
 * The full scenario → test map is in docs/test-report.md (generated by tools/test-report.ts).
 */
import { describe, it, expect, beforeAll } from 'vitest';
import { openDb, migrate, seedDemo, type Db } from '@pawsure/db';
import { createApp } from '../src/app.js';
import { mockAdapters } from '../src/adapters.js';
import { demoClock } from '../src/clock.js';

let db: Db, app: ReturnType<typeof createApp>, adapters: ReturnType<typeof mockAdapters>, clock: ReturnType<typeof demoClock>, neha: string;
const D1 = '2026-11-08', D2 = '2026-11-09', at = (hm: string, d = D1) => `${d}T${hm}:00+05:30`, HH = '/v1/households/hh_demo', SUNITA = '+919000000035';
const call = async <T = Record<string, unknown>>(method: string, path: string, body?: unknown, token?: string) => {
  const r = await app.request(path, { method, headers: { 'content-type': 'application/json', ...(token ? { authorization: 'Bearer ' + token } : {}) }, body: body ? JSON.stringify(body) : undefined });
  return { status: r.status, body: await r.json() as T };
};
const signIn = async (phone: string) => { const r = await call<{ demoCode: string }>('POST', '/auth/otp/request', { phone }); return (await call<{ token: string }>('POST', '/auth/otp/verify', { phone, code: r.body.demoCode })).body.token; };
const tick = () => call<{ sent: string[] }>('POST', '/jobs/tick');

beforeAll(async () => {
  db = await openDb({ dataDir: 'memory' }); await migrate(db); await seedDemo(db);
  adapters = mockAdapters(); clock = demoClock(at('08:00'));
  app = createApp({ db, adapters, clock, pepper: 'test', demoMode: true });
  neha = await signIn('+919800000021'); await tick();
}, 60000);

describe('#1 new owner: pet + routine → Who’s caring today, no optional fields', () => {
  it('works end to end with only the required fields', async () => {
    const t = await signIn('+919811444555');
    expect((await call('POST', '/v1/consents', { items: [{ kind: 'terms', version: 'T-1.0', granted: true }, { kind: 'privacy', version: 'PN-1.0', granted: true }], language: 'en' }, t)).status).toBeLessThan(300);
    const hh = (await call<{ id: string }>('POST', '/v1/households', { displayName: 'Asha', language: 'en', society: 'Raheja Vihar, Powai' }, t)).body.id;
    const pet = (await call<{ id: string }>('POST', `/v1/households/${hh}/pets`, { name: 'Coco', food: 'Dry food 150 g at 8 AM and 7 PM', allergies: 'None known', medicines: 'None', vet_name: 'Dr. Rao', vet_phone: '+91 22 5555 0101' }, t)).body.id;
    expect(pet).toBeTruthy();
    expect((await call('POST', `/v1/households/${hh}/routine`, { petId: pet, title: 'Dinner', type: 'feeding', due: 1200, assignee: 'owner', oneOffToday: true }, t)).status).toBeLessThan(300);
    const today = (await call<{ tasks: { title: string }[]; day: { mode: string } }>('GET', `/v1/households/${hh}/today`, undefined, t)).body;
    expect(today.tasks.map(x => x.title)).toContain('Dinner');
    expect((await call('PUT', `/v1/households/${hh}/day`, { mode: 'tracked' }, t)).status).toBe(200);
  });
});

describe('#10 / #24 Trusted Helper day', () => {
  it('#10 no helper prompts, no escalation, no points; incidents and health still work', async () => {
    expect((await call('PUT', `${HH}/day`, { mode: 'trusted' }, neha)).status).toBe(200);
    const before = adapters.outbox.length;
    clock.set(at('15:00')); await tick();
    const sent = adapters.outbox.slice(before);
    expect(sent.some(o => o.template.startsWith('W3_PROMPT'))).toBe(false);
    expect((await db.query(`select 1 from audit_log where action='escalation.step' and household_id='hh_demo' and detail->>'task' like $1`, [`%_${D1}`])).length).toBe(0);
    const day = (await call<{ tasks: { points: { kind: string } }[] }>('GET', `${HH}/today`, undefined, neha)).body;
    expect(day.tasks.every(t => t.points.kind === 'none')).toBe(true);
    expect((await call('POST', `${HH}/incidents`, { category: 'not_eating' }, neha)).status).toBeLessThan(300);
  });
  it('#24 no “Covered” tap by midnight → Unknown, not covered', async () => {
    clock.set(at('23:59'));
    const r = await call<{ household: string }>('POST', `${HH}/day/close`, {}, neha);
    expect(r.body.household).toBe('Unknown');
    const stored = await db.query<{ status: string }>(`select status from care_days where household_id='hh_demo' and care_date=$1`, [D1]);
    expect(stored.every(s => s.status === 'Unknown')).toBe(true);
  });
});

describe('#5 no gate app: random photo checks about 1 in 5', () => {
  it('helpers who use calls are asked for a photo on a sample of tasks, at the 1-in-5 rate', async () => {
    await db.query(`update households set gate_app=false where id='hh_demo'`);
    await db.query(`update memberships set method='ivr' where id='m_sunita'`);
    for (let i = 0; i < 30; i++) await db.query(`insert into routine_tasks(id, household_id, pet_id, title, task_type, due_minute, min_minutes, escalation_profile, assignee_membership_id, effective_from) values ($1,'hh_demo','bruno',$2,'water',600,1,'standard','m_sunita',$3)`, ['rs' + i, 'Water top-up ' + i, D2]);
    clock.set(at('09:55', D2)); await tick();
    const samples = await db.query<{ every: number }>(`select (detail->>'every')::int as every from audit_log where action='prompt.photo_sample' and detail->>'task' like $1`, [`%_${D2}`]);
    expect(samples.length).toBeGreaterThan(0);
    expect(samples.length).toBeLessThan(20);
    samples.forEach(s => expect(s.every).toBe(5));
    const prompts = adapters.outbox.filter(o => o.template.startsWith('W3_PROMPT'));
    expect(prompts.length).toBeGreaterThanOrEqual(30);
  });
  it('the own-helper path still works without a gate app (IVR code)', async () => {
    const code = (await call<{ codes: Record<string, string> }>('GET', `${HH}/code-cards/current`, undefined, neha)).body.codes['9']!;
    const r = await call<{ codeOk: boolean }>('POST', '/webhooks/ivr', { callId: 'acc-ivr', from: SUNITA, event: 'code', taskId: `rs0_${D2}`, digits: code });
    expect(r.body.codeOk).toBe(true);
  });
});

describe('#17 rights request from WhatsApp stops future processing', () => {
  it('“delete my data” creates an erasure request, pauses check-ins, tells the owner and is audited', async () => {
    await call('POST', '/webhooks/whatsapp', { from: SUNITA, messageId: 'acc-del', type: 'text', text: 'delete my data' });
    const rr = (await db.query<{ kind: string; channel: string }>(`select kind, channel from rights_requests where channel='whatsapp'`))[0]!;
    expect(rr).toEqual({ kind: 'erasure', channel: 'whatsapp' });
    expect((await db.query<{ paused: boolean }>(`select paused from memberships where id='m_sunita'`))[0]!.paused).toBe(true);
    expect((await db.query(`select 1 from audit_log where action='rights.request' and detail->>'processingStopped'='true'`)).length).toBe(1);
    const photo = await call('POST', '/webhooks/whatsapp', { from: SUNITA, messageId: 'acc-after', type: 'photo', taskId: `rs1_${D2}`, mediaRef: 'after-1', caption: '1234' });
    expect(photo.status).toBe(409);
  });
});
